package com.cpf.core.common.database;import com.cpf.core.api.database.CpfDataAccessIntent;import org.springframework.jdbc.datasource.lookup.AbstractRoutingDataSource;import org.springframework.transaction.support.TransactionSynchronizationManager;/** Primary/Replica routing datasource. Transaction write는 항상 WRITE를 선택해 read-after-write 일관성을 보호합니다. */public class CpfReadWriteRoutingDataSource extends AbstractRoutingDataSource {@Override protected Object determineCurrentLookupKey(){CpfDataAccessIntent explicit=CpfDataAccessContext.current();if(explicit==CpfDataAccessIntent.WRITE)return "WRITE";if(TransactionSynchronizationManager.isActualTransactionActive()&&!TransactionSynchronizationManager.isCurrentTransactionReadOnly())return "WRITE";return explicit==CpfDataAccessIntent.READ||TransactionSynchronizationManager.isCurrentTransactionReadOnly()?"READ":"WRITE";}}